    low: [['road', 'On the road'], ['wilds', 'In the wild country'], ['ruins', 'Among old stones'], ['settlement', 'In a village'], ['farm', 'On a holding'], ['water', 'By the water']],
    west: [['road', 'On the trail'], ['wilds', 'In open country'], ['ruins', 'In a ghost town'], ['settlement', 'In town'], ['farm', 'At a ranch'], ['water', 'By the river']],
